package edu.uiu.aoop.careerforge.controller;

import edu.uiu.aoop.careerforge.dto.ApiResponse;
import edu.uiu.aoop.careerforge.exception.ApiException;
import edu.uiu.aoop.careerforge.security.AppPrincipal; import java.util.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/student") public class StudentController { private final JdbcTemplate jdbc; public StudentController(JdbcTemplate jdbc){this.jdbc=jdbc;} @GetMapping("/overview") Map<String,Object> overview(@AuthenticationPrincipal AppPrincipal p){Map<String,Object> result=new LinkedHashMap<>();Double readiness=jdbc.query("SELECT readiness_score FROM student_profiles WHERE user_id=?",rs->rs.next()?rs.getDouble(1):0d,p.id());Integer applications=jdbc.queryForObject("SELECT COUNT(*) FROM applications WHERE user_id=? AND status<>'withdrawn'",Integer.class,p.id());Integer assessments=jdbc.queryForObject("SELECT COUNT(*) FROM assessment_attempts WHERE user_id=?",Integer.class,p.id());Integer events=jdbc.queryForObject("SELECT COUNT(*) FROM event_registrations WHERE user_id=?",Integer.class,p.id());result.put("readinessScore",readiness);result.put("applications",applications);result.put("assessments",assessments);result.put("events",events);result.put("calculation",Map.of("profileCompletion",jdbc.query("SELECT profile_completion FROM student_profiles WHERE user_id=?",rs->rs.next()?rs.getDouble(1):0d,p.id())));return result;} }
